import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"\'\]\)]+'
    urls = re.findall(url_pattern, myString or "")
    domains = []
    for u in urls:
        parsed = urllib.parse.urlparse(u)
        netloc = parsed.netloc.strip().lower()
        if not netloc:
            continue
        host = netloc.split('@')[-1].split(':')[0].strip().strip('.')
        if host:
            domains.append(host)

    unique_domains = list(dict.fromkeys(domains))
    results = {}

    for domain in unique_domains:
        try:
            resp = requests.get(
                "https://ip-api.com/json/" + urllib.parse.quote(domain, safe=""),
                params={"key": API_KEY},
                timeout=10
            )
            if resp.status_code != 200:
                results[domain] = None
                continue
            try:
                results[domain] = resp.json()
            except ValueError:
                results[domain] = json.loads(resp.text)
        except Exception:
            results[domain] = None

    return results

