API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    resp = requests.get(url, timeout=5)
    content = resp.content

    if not content:
        return {}

    src_enc = from_encoding
    if src_enc is None:
        det = chardet.detect(content)
        src_enc = det.get("encoding") if isinstance(det, dict) else None

    if not src_enc:
        raise ValueError("Unable to detect encoding for non-empty content")

    text = content.decode(src_enc, errors="strict")
    text = text.encode(to_encoding, errors="strict").decode(to_encoding, errors="strict")

    return json.loads(text)

