def task_func(myString, API_KEY):
    url_pattern = r'(?:(?:https?://)|(?:www\.))[^\s<>"\'\)\]]+'
    urls = re.findall(url_pattern, myString or "")

    domains = []
    seen = set()
    for u in urls:
        candidate = u
        if not re.match(r'^https?://', candidate, flags=re.IGNORECASE):
            candidate = "http://" + candidate
        parsed = urllib.parse.urlparse(candidate)
        domain = parsed.hostname
        if domain and domain not in seen:
            seen.add(domain)
            domains.append(domain)

    results = {}
    endpoint = "https://api.ipgeolocation.io/ipgeo"
    for domain in domains:
        try:
            resp = requests.get(endpoint, params={"apiKey": API_KEY, "ip": domain}, timeout=10)
            if resp.status_code != 200:
                results[domain] = None
                continue
            results[domain] = json.loads(resp.text)
        except Exception:
            results[domain] = None

    return results

