IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    data = ip_address
    if isinstance(ip_address, str):
        try:
            data = json.loads(ip_address)
        except (json.JSONDecodeError, TypeError):
            data = ip_address

    candidate = None

    if isinstance(data, dict):
        for k in ("ip", "ip_address", "address", "public_ip"):
            v = data.get(k, None)
            if isinstance(v, str) and v.strip():
                candidate = v.strip()
                break
        if candidate is None:
            for v in data.values():
                if isinstance(v, str):
                    m = re.search(IP_REGEX, v)
                    if m:
                        candidate = m.group(0)
                        break
    elif isinstance(data, str):
        s = data.strip()
        m = re.search(IP_REGEX, s)
        if m:
            candidate = m.group(0)

    if not candidate or not re.fullmatch(IP_REGEX, candidate):
        return 'Invalid IP address received'

    parts = candidate.split(".")
    if len(parts) != 4:
        return 'Invalid IP address received'

    try:
        if any(not (0 <= int(p) <= 255) for p in parts):
            return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'

    return candidate

