from collections import Counter
def task_func(json_dir_path, word_count):
    counter = Counter()

    if not os.path.isdir(json_dir_path):
        return []

    for name in os.listdir(json_dir_path):
        if not name.lower().endswith(".json"):
            continue
        path = os.path.join(json_dir_path, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue

        text = ""
        if isinstance(data, dict):
            val = data.get("text", "")
            if isinstance(val, str):
                text = val
        if not text:
            continue

        s = pd.Series([text], dtype="string").fillna("").str.lower()
        s = s.str.replace(r"[^a-z0-9\s]+", " ", regex=True).str.replace(r"\s+", " ", regex=True).str.strip()
        words = s.iloc[0].split()
        counter.update(words)

    try:
        n = int(word_count)
    except Exception:
        n = 0
    if n <= 0:
        return []
    return counter.most_common(n)

