        raise Exception("Invalid url")
    url = url.strip()
    if not (url.startswith("http://") or url.startswith("https://")):
        raise Exception("Invalid url")

    try:
        resp = requests.get(url, headers=HEADERS, params=parameters, timeout=20)
    except Exception as e:
        raise Exception("url cannot be accessed") from e

    if not hasattr(resp, "status_code") or resp.status_code != 200:
        raise Exception("url cannot be accessed")

    try:
        payload = resp.json()
    except Exception:
        try:
            payload = json.loads(resp.text)
        except Exception as e:
            raise Exception("invalid data") from e

    records = None
    if isinstance(payload, list):
        records = payload
    elif isinstance(payload, dict):
        if isinstance(payload.get("data", None), list):
            records = payload["data"]
        else:
            list_candidates = [v for v in payload.values() if isinstance(v, list)]
            if len(list_candidates) == 1:
                records = list_candidates[0]

    if records is None or not isinstance(records, list):
        raise Exception("invalid data")
    if len(records) == 0:
        raise Exception("empty data")

    try:
        df = pd.DataFrame.from_records(records)
