def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []

    if isinstance(input_data, (dict, list)):
        data = input_data
    elif isinstance(input_data, (bytes, bytearray)):
        try:
            data = json.loads(input_data.decode("utf-8", errors="ignore"))
        except Exception:
            return []
    elif isinstance(input_data, str):
        try:
            data = json.loads(input_data)
        except Exception:
            return []
    else:
        return []

    names = []
    emails = []

    def add_name(x):
        if x is None:
            return
        if not isinstance(x, str):
            x = str(x)
        x = x.strip()
        if x and x not in names:
            names.append(x)

    def add_email(x):
        if x is None:
            return
        if not isinstance(x, str):
            x = str(x)
        x = x.strip()
        if x and x not in emails:
            emails.append(x)

    def walk(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in {"name", "fullname", "full_name", "recipient_name"} and isinstance(v, (str, int, float)):
                    add_name(v)
                if lk in {"email", "e-mail", "recipient_email", "recipientemail", "to", "to_email"} and isinstance(v, (str, int, float)):
                    add_email(v)
                if lk in {"names"} and isinstance(v, list):
                    for item in v:
                        if isinstance(item, (str, int, float)):
                            add_name(item)
                        elif isinstance(item, dict):
                            walk(item)
                if lk in {"recipients", "recipient", "people", "contacts", "to_list"} and isinstance(v, list):
                    for item in v:
                        walk(item)
                walk(v)
        elif isinstance(obj, list):
            for item in obj:
                walk(item)

    walk(data)

    message = "Subject: Extracted Names\n\n" + ("\n".join(names) if names else "")
    to_addrs = emails[:] if emails else []

    if to_addrs:
        if smtp is None:
            s = smtplib.SMTP(smtp_server, smtp_port)
            try:
                s.ehlo()
                s.starttls()
                s.ehlo()
                s.login(email_address, email_password)
                s.sendmail(email_address, to_addrs, message)
            finally:
                try:
                    s.quit()
                except Exception:
                    pass
        else:
            smtp.sendmail(email_address, to_addrs, message)

    return names

