import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    try:
        with open(file_path, "r") as f:
            data = json.load(f)
    except Exception as e:
        raise ValueError("Invalid JSON file") from e

    if not isinstance(data, dict):
        raise ValueError("Top-level JSON must be an object")

    required = INPUT_JSON.get("required", [])
    for key in required:
        if key not in data:
            raise ValueError(f"Missing required attribute: {key}")

    properties = INPUT_JSON.get("properties", {})
    for key, rules in properties.items():
        if key in data and "type" in rules:
            expected_type = rules["type"]
            if not isinstance(data[key], expected_type):
                raise ValueError(f"Type mismatch for attribute: {key}")

    if "email" in data:
        email_value = data["email"]
        if not isinstance(email_value, str):
            raise ValueError("Type mismatch for attribute: email")
        if re.match(EMAIL_REGEX, email_value.strip().lower()) is None:
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError("Requested attribute is missing")

    if attribute in properties and "type" in properties[attribute]:
        expected_type = properties[attribute]["type"]
        if not isinstance(data[attribute], expected_type):
            raise ValueError(f"Type mismatch for attribute: {attribute}")

    return data[attribute]

