from glob import glob
def task_func(directory, string):
    pattern = directory.rstrip("/\\") + "/**/*.json"
    files = glob(pattern, recursive=True)
    if not files:
        return []

    def contains_target(obj):
        if isinstance(obj, str):
            return obj == string
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(k, str) and k == string:
                    return True
                if contains_target(v):
                    return True
            return False
        if isinstance(obj, list):
            for item in obj:
                if contains_target(item):
                    return True
            return False
        return False

    matched = []
    for path in files:
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue
        if contains_target(data):
            matched.append(path)

    return matched

