import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    try:
        with open(input_file, "r") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return pd.DataFrame(columns=["mean", "median"]).astype(float)

    values_by_key = defaultdict(list)

    if isinstance(data, list):
        for item in data:
            if not isinstance(item, dict):
                continue
            for k, v in item.items():
                if isinstance(v, (bool, str)) or v is None:
                    continue
                if isinstance(v, (int, float, np.integer, np.floating)) and np.isfinite(v):
                    values_by_key[k].append(float(v))

    keys = sorted(values_by_key.keys())
    rows = []
    for k in keys:
        vals = np.array(values_by_key[k], dtype=float)
        if vals.size == 0:
            mean_val = np.nan
            median_val = np.nan
        else:
            mean_val = float(np.mean(vals))
            median_val = float(np.median(vals))
        rows.append((k, mean_val, median_val))

    df = pd.DataFrame(rows, columns=["variable", "mean", "median"]).set_index("variable").sort_index()
    return df

