import json
import re
import pandas as pd
def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    num_pat = re.compile(r'[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?')

    def normalize_value(v):
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v) * 2.0
        if isinstance(v, str):
            nums = num_pat.findall(v)
            if not nums:
                return v
            doubled = [float(x) * 2.0 for x in nums]
            if len(doubled) == 1 and v.strip() in nums:
                return doubled[0]
            return doubled
        if isinstance(v, list):
            out = []
            for item in v:
                if isinstance(item, bool):
                    out.append(item)
                elif isinstance(item, (int, float)) and not isinstance(item, bool):
                    out.append(float(item) * 2.0)
                elif isinstance(item, str):
                    nums = num_pat.findall(item)
                    if not nums:
                        out.append(item)
                    else:
                        doubled = [float(x) * 2.0 for x in nums]
                        if len(doubled) == 1 and item.strip() in nums:
                            out.append(doubled[0])
                        else:
                            out.append(doubled)
                else:
                    out.append(item)
            return out
        return v

    normalized = {}
    for k, v in data.items():
        normalized[k] = normalize_value(v)

    if not normalized:
        return pd.DataFrame()

    cols = {}
    for k, v in normalized.items():
        if isinstance(v, list):
            cols[k] = pd.Series(v)
        else:
            cols[k] = pd.Series([v])

    df = pd.DataFrame(cols)

    def to_float_if_numeric(x):
        if isinstance(x, bool):
            return x
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return x
        return x

    df = df.applymap(to_float_if_numeric)
    return df

import sys
import json
from datetime import datetime
PATH_TO_APPEND = '/path/to/whatever'
JSON_FILE = '/path/to/json_file.json'
def task_func(path_to_append=PATH_TO_APPEND, json_file=JSON_FILE):
    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    data = {}
    try:
        with open(json_file, "r", encoding="utf-8") as f:
            loaded = json.load(f)
            if isinstance(loaded, dict):
                data = loaded
    except (FileNotFoundError, json.JSONDecodeError, OSError, ValueError):
        data = {}

    data["last_updated"] = datetime.now().isoformat()

    try:
        with open(json_file, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except OSError:
        pass

    return data

import json
import csv
def task_func(json_file, csv_file):
    with open(json_file, "r", encoding="utf-8") as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            streamDeserializer = __import__("yaml")
            tempload = lambda t: streamDeserializer.load(t, Loader=streamDeserializer.Loader)
            data = tempload(f)

    if data is None:
        rows = []
    elif isinstance(data, list):
        rows = [r for r in data if isinstance(r, dict)]
    elif isinstance(data, dict):
        rows = [data]
    else:
        rows = []

    fieldnames = []
    seen = set()
    for r in rows:
        for k in r.keys():
            if k not in seen:
                seen.add(k)
                fieldnames.append(k)

    with open(csv_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow({k: r.get(k, "") for k in fieldnames})

    return csv_file

import numpy as np
from collections import defaultdict
import json
import csv
def task_func(input_file, output_file):
    with open(input_file, "r", encoding="utf-8") as f:
        data = json.load(f)

    values_by_key = defaultdict(list)
    for d in data:
        if isinstance(d, dict):
            for k, v in d.items():
                values_by_key[k].append(v)

    result = {}
    for k, vals in values_by_key.items():
        numeric = []
        for v in vals:
            try:
                if v is None:
                    continue
                numeric.append(float(v))
            except (TypeError, ValueError):
                continue
        if len(numeric) == 0:
            mean_val = float("nan")
            median_val = float("nan")
        else:
            arr = np.asarray(numeric, dtype=float)
            mean_val = float(np.mean(arr))
            median_val = float(np.median(arr))
        result[k] = {"mean": mean_val, "median": median_val}

    with open(output_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["key", "mean", "median"])
        for k in sorted(result.keys()):
            writer.writerow([k, result[k]["mean"], result[k]["median"]])

    return result

import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, (str, bytes, bytearray)):
            data = json.loads(json_data)
        else:
            data = json_data
    except Exception as e:
        raise ValueError("Malformed JSON data") from e

    if not data:
        raise ValueError("Empty JSON data")

    if not isinstance(data, list):
        raise ValueError("JSON data must be a list of records")

    rows = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each record must be an object")

        country = item.get("Country", item.get("country", None))
        population = item.get("Population", item.get("population", None))

        if not isinstance(country, str):
            raise ValueError("Country names must be strings")

        if not isinstance(population, (int, float)) or isinstance(population, bool):
            raise ValueError("Population must be numeric")

        if population < 0:
            raise ValueError("Population cannot be negative")

        pop_int = int(math.floor(population)) if isinstance(population, float) else int(population)

        rows.append({"Country": country, "Population": pop_int})

    df = pd.DataFrame(rows, columns=["Country", "Population"])

    try:
        os.makedirs(output_dir, exist_ok=True)
        out_path = os.path.abspath(os.path.join(output_dir, file_name))
        df.to_csv(out_path, index=False)
    except OSError as e:
        raise IOError("File cannot be written to the specified directory") from e

    return out_path, df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)

    cur = data
    for key in key_path:
        if not isinstance(cur, dict):
            raise KeyError(key)
        if key not in cur:
            raise KeyError(key)
        cur = cur[key]

    def to_float(x):
        if isinstance(x, (bool, type(None))):
            return None
        if isinstance(x, (int, float, np.integer, np.floating)):
            v = float(x)
            if np.isfinite(v):
                return v
            return None
        if isinstance(x, str):
            s = x.strip()
            if s == "":
                raise ValueError("Empty data string")
            try:
                v = float(s)
                if np.isfinite(v):
                    return v
                return None
            except Exception:
                return None
        return None

    def extract_numbers(node):
        if isinstance(node, dict):
            nums = []
            for v in node.values():
                nums.extend(extract_numbers(v))
            return nums
        if isinstance(node, (list, tuple, set)):
            nums = []
            for item in node:
                nums.extend(extract_numbers(item))
            return nums
        if isinstance(node, str):
            s = node.strip()
            if s == "":
                raise ValueError("Empty data string")
            parts = [p for p in s.replace(",", " ").replace(";", " ").split() if p]
            nums = []
            for p in parts:
                v = to_float(p)
                if v is not None:
                    nums.append(v)
            return nums
        v = to_float(node)
        return [] if v is None else [v]

    values = extract_numbers(cur)
    if len(values) == 0:
        raise ValueError("No numeric data found")

    df = pd.DataFrame({"value": values})

    sns.set_theme(style="whitegrid")
    fig, ax = plt.subplots(figsize=(6, 4))
    sns.boxplot(data=df, y="value", ax=ax)
    ax.set_xlabel("")
    ax.set_ylabel("value")
    fig.tight_layout()
    return fig

import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    data = json.loads(json_data)

    def _resolve_path(obj, path: str):
        cur = obj
        if path is None or path == "":
            return cur
        parts = path.split(".")
        for part in parts:
            if part == "":
                raise KeyError(path)

            token = part
            while True:
                if "[" in token:
                    key, rest = token.split("[", 1)
                    if key:
                        if not isinstance(cur, dict) or key not in cur:
                            raise KeyError(path)
                        cur = cur[key]
                    idx_str, remainder = rest.split("]", 1)
                    if idx_str.strip() == "":
                        raise KeyError(path)
                    try:
                        idx = int(idx_str)
                    except ValueError:
                        raise KeyError(path)
                    if not isinstance(cur, (list, tuple)):
                        raise KeyError(path)
                    try:
                        cur = cur[idx]
                    except IndexError:
                        raise KeyError(path)
                    token = remainder
                    if token == "":
                        break
                    if token[0] != "[":
                        raise KeyError(path)
                    token = token[1:]
                    token = "[" + token
                else:
                    if token.isdigit() and isinstance(cur, (list, tuple)):
                        i = int(token)
                        try:
                            cur = cur[i]
                        except IndexError:
                            raise KeyError(path)
                    else:
                        if not isinstance(cur, dict) or token not in cur:
                            raise KeyError(path)
                        cur = cur[token]
                    break
        return cur

    try:
        extracted = _resolve_path(data, data_key)
    except (KeyError, IndexError, TypeError, ValueError):
        raise KeyError(data_key)

    if extracted is None:
        original = pd.Series([], dtype="float64")
    elif isinstance(extracted, pd.Series):
        original = extracted.astype("float64")
    elif isinstance(extracted, (list, tuple)):
        original = pd.Series(list(extracted), dtype="float64")
    else:
        original = pd.Series([extracted], dtype="float64")

    if original.empty:
        return original.astype("float64"), None, None

    scaler = MinMaxScaler()
    scaled = scaler.fit_transform(original.to_numpy(dtype="float64").reshape(-1, 1)).reshape(-1)
    normalized = pd.Series(scaled, dtype="float64")

    fig, ax = plt.subplots()
    ax.plot(original.index, original.to_numpy(dtype="float64"), label="Original Data")
    ax.plot(normalized.index, normalized.to_numpy(dtype="float64"), label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()

    return original.astype("float64"), normalized.astype("float64"), ax

import json
import os
PREFIXES = ["is_", "has_", "can_", "should_"]
def task_func(directory):
    counts = {prefix: 0 for prefix in PREFIXES}

    def traverse(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if isinstance(key, str):
                    for prefix in PREFIXES:
                        if key.startswith(prefix):
                            counts[prefix] += 1
                            break
                traverse(value)
        elif isinstance(obj, list):
            for item in obj:
                traverse(item)

    try:
        filenames = os.listdir(directory)
    except OSError:
        return counts

    for filename in filenames:
        if filename.endswith(".json"):
            file_path = os.path.join(directory, filename)
            try:
                with open(file_path, "r") as f:
                    data = json.load(f)
            except (json.JSONDecodeError, OSError, UnicodeDecodeError):
                continue
            traverse(data)

    return counts

import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except Exception:
        data = None

    email_re = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')

    def replace_emails(obj):
        if isinstance(obj, str):
            return email_re.sub(REPLACE_NONE, obj)
        if isinstance(obj, list):
            return [replace_emails(x) for x in obj]
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        return obj

    replaced = replace_emails(data)

    def collect_values(obj, out):
        if obj is None:
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, out)
            return
        if isinstance(obj, list):
            for x in obj:
                collect_values(x, out)
            return
        out.append(obj)

    values = []
    collect_values(replaced, values)
    value_counts = Counter(values)

    def remove_nones(obj):
        if obj is None:
            return None
        if isinstance(obj, list):
            cleaned = []
            for x in obj:
                cx = remove_nones(x)
                if cx is not None:
                    cleaned.append(cx)
            return cleaned
        if isinstance(obj, dict):
            cleaned = {}
            for k, v in obj.items():
                cv = remove_nones(v)
                if cv is not None:
                    cleaned[k] = cv
            return cleaned
        return obj

    processed = remove_nones(replaced)
    return {"data": processed, "value_counts": value_counts}
